"""GENERATED by gen/generate.py from ffi/schema/shapes.json. Do not edit.

Facade objects carrying EXACTLY the manifest's values.

The value rules live in `ffi/schema/emit/values.py` and are a pure function of
(field path, element index), which is what lets five slices produce identical
bytes without sharing a data file.  This module applies those rules to the
facade constructors, so a mismatch against `generated/manifest.json` is a defect
in this slice (the manifest is validated against prost 0.14.4 and a second,
independent encoder).
"""

import os
import sys


def _find_ffi_root():
    """Walk up until `schema/shapes.json` is found.

    NOT an absolute path baked in at generate time, which is what the first
    version did: a clone of this branch at any other path then regenerated a
    different file and `generate.py --check` refused the tree as stale, so the
    committed sources could not rebuild themselves. Defect D4, and it was found
    by cloning the pushed branch and building it, not by reading the code.
    """
    d = os.path.dirname(os.path.abspath(__file__))
    for _ in range(12):
        if os.path.exists(os.path.join(d, "schema", "shapes.json")):
            return d
        parent = os.path.dirname(d)
        if parent == d:
            break
        d = parent
    raise RuntimeError("cannot find the ffi/ root above %s" % __file__)


_FFI = _find_ffi_root()
sys.path.insert(0, os.path.join(_FFI, "schema", "emit"))

import shapes as S      # noqa: E402
import values as V      # noqa: E402
import payloads as P    # noqa: E402

SCHEMA = S.load()


def _absent(f, mode):
    return mode == "all_absent"


def build_element(ctor, stampctor, idx, mode):
    """One ListResultsResponse element, from the same rules payloads.py applies."""
    kw = {}
    for f in S.fields(SCHEMA["messages"]['ResultRaw']):
        path = "%s.%s" % ('ResultRaw', f["name"])
        nm, k = f["name"], f["kind"]
        if _absent(f, mode):
            kw[nm] = {"string": "", "bytes": b"", "message": None}.get(k, 0)
            if k == "bool":
                kw[nm] = False
            continue
        if k == "string":
            kw[nm] = {"guid": V.guid, "word": V.word,
                      "sentence": V.sentence}[f.get("value", "word")](path, idx)
        elif k == "bytes":
            kw[nm] = V.blob(path, idx)
        elif k == "enum":
            kw[nm] = V.enum_value(SCHEMA["enums"][f["of"]]["values"], idx)
        elif k == "bool":
            kw[nm] = bool(V.scalar("bool", path, idx))
        elif k in ("int32", "int64"):
            kw[nm] = int(V.scalar(k, path, idx))
        elif k == "message":
            t = V.timestamp(path, idx)
            kw[nm] = stampctor(seconds=t["seconds"], nanos=t["nanos"])
        else:
            raise NotImplementedError(k)
    return ctor(**kw)


def build(payload_id, root_ctor, elem_ctor, stamp_ctor):
    spec = SCHEMA["payloads"][payload_id]
    mode = spec.get("mode")
    elems = [build_element(elem_ctor, stamp_ctor, j, mode)
             for j in range(spec["count"])]
    return root_ctor(results=elems, page=1, total=spec["count"])


def reference(payload_id):
    """The canonical bytes, straight from the emitter the manifest came from."""
    return P.build(SCHEMA, payload_id, SCHEMA["payloads"][payload_id])
